6LoWPAN.ejemplo:
# Captura lógica de compresión IPHC (RFC 6282)
[802.15.4 Header (23B)] -> [IPHC Dispatch: 0x7A 0x11] -> [Compressed UDP] -> [CoAP Payload]
# Router de borde Linux (wpan0 -> eth0) con radvd:
interface lowpan0 {
  AdvSendAdvert on;
  prefix fd00:db8:1::/64 { AdvOnLink on; AdvAutonomous on; };
};

Detección de manipulación.ejemplo:
# Flujo lógico de respuesta ante evento de manipulación física (Tamper IRQ)
void on_tamper_interrupt(tamper_source_t src) {
    secure_element_zeroize_keys();     // Borrado inmediato de claves privadas
    nvm_write_audit_flag(TAMPER_FLAG); // Registro persistente del incidente
    system_halt_safe_state();          // Bloqueo hasta reacondicionamiento autorizado
}
